//! Agent-facing contract: JSON output, exit codes, --wait, idempotency,
//! dry runs, --select, schema and the MCP server.

use std::io::Write;
use std::process::{Command, Output, Stdio};

use serde_json::{Value, json};

fn test_url() -> String {
    std::env::var("MSC_TEST_URL").unwrap_or_else(|_| "http://localhost:7700".to_string())
}

fn config_path(name: &str) -> String {
    format!("{}/{name}.toml", env!("CARGO_TARGET_TMPDIR"))
}

fn cli() -> Command {
    let mut cmd = Command::new(env!("CARGO_BIN_EXE_msc"));
    cmd.env("MSC_URL", test_url())
        .env("MSC_CONFIG", config_path("agent-config"))
        .env_remove("MSC_API_KEY")
        .env_remove("MSC_PROJECT")
        .env_remove("MSC_WAIT")
        .stdin(Stdio::null());
    cmd
}

fn run(args: &[&str]) -> Output {
    cli().args(args).output().unwrap()
}

fn run_stdin(args: &[&str], input: &[u8]) -> Output {
    let mut child = cli()
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    child.stdin.take().unwrap().write_all(input).unwrap();
    child.wait_with_output().unwrap()
}

fn stdout_json(o: &Output) -> Value {
    serde_json::from_slice(&o.stdout).unwrap_or_else(|e| {
        panic!(
            "stdout is not JSON ({e}): {}",
            String::from_utf8_lossy(&o.stdout)
        )
    })
}

fn stderr_error(o: &Output) -> Value {
    let v: Value = serde_json::from_slice(&o.stderr).unwrap_or_else(|e| {
        panic!(
            "stderr is not JSON ({e}): {}",
            String::from_utf8_lossy(&o.stderr)
        )
    });
    v["error"].clone()
}

fn code(o: &Output) -> i32 {
    o.status.code().unwrap()
}

fn unique_index() -> String {
    format!("agent_{}", uuid::Uuid::new_v4().simple())
}

/// Creates an index (waiting for it) and deletes it on drop.
struct TempIndex(String);

impl TempIndex {
    fn new() -> Self {
        let uid = unique_index();
        let o = run(&["index", "create", &uid, "--primary-key", "id", "--wait"]);
        assert_eq!(code(&o), 0, "{}", String::from_utf8_lossy(&o.stderr));
        TempIndex(uid)
    }
}

impl Drop for TempIndex {
    fn drop(&mut self) {
        let _ = run(&["index", "delete", &self.0]);
    }
}

#[test]
fn piped_output_is_compact_json() {
    let o = run(&["health"]);
    assert_eq!(code(&o), 0);
    let text = String::from_utf8_lossy(&o.stdout);
    assert_eq!(text.trim(), r#"{"status":"available"}"#);
}

#[test]
fn pretty_flag_forces_human_output() {
    let o = run(&["health", "--pretty"]);
    assert!(String::from_utf8_lossy(&o.stdout).contains("\n  \"status\""));
}

#[test]
fn not_found_exits_4_with_json_error() {
    let o = run(&["index", "get", &unique_index()]);
    assert_eq!(code(&o), 4);
    assert!(o.stdout.is_empty());
    let err = stderr_error(&o);
    assert_eq!(err["kind"], "not_found");
    assert_eq!(err["code"], "index_not_found");
    assert_eq!(err["httpStatus"], 404);
    assert!(err["link"].is_string());
}

#[test]
fn unreachable_server_exits_6() {
    let o = run(&["health", "--url", "http://127.0.0.1:9"]);
    assert_eq!(code(&o), 6);
    let err = stderr_error(&o);
    assert_eq!(err["kind"], "network");
    assert!(err["hint"].is_string());
}

#[test]
fn usage_errors_exit_2_with_json_error() {
    let o = run(&["index", "create"]);
    assert_eq!(code(&o), 2);
    assert_eq!(stderr_error(&o)["code"], "missing_argument");

    let o = run(&["settings", "get", "x", "not-a-setting"]);
    assert_eq!(code(&o), 2);
    assert_eq!(stderr_error(&o)["code"], "invalid_settings_sub_resource");
}

#[test]
fn interactive_commands_refuse_without_terminal() {
    for args in [
        &["settings", "edit", "x"][..],
        &["search", "x", "-i"][..],
        &["chat", "-i"][..],
    ] {
        let o = run(args);
        assert_eq!(code(&o), 2, "{args:?}");
        assert_eq!(stderr_error(&o)["code"], "non_interactive", "{args:?}");
    }
}

#[test]
fn wait_returns_final_task_and_failures_exit_7() {
    let idx = TempIndex::new();

    // Creating it again fails asynchronously.
    let o = run(&["index", "create", &idx.0, "--wait"]);
    assert_eq!(code(&o), 7);
    let task = stdout_json(&o);
    assert_eq!(task["status"], "failed");
    let err = stderr_error(&o);
    assert_eq!(err["kind"], "task_failed");
    assert_eq!(err["code"], "index_already_exists");
    assert_eq!(err["taskUid"], task["uid"]);

    // `task wait` reports the same failure.
    let o = run(&["task", "wait", &task["uid"].to_string()]);
    assert_eq!(code(&o), 7);
}

#[test]
fn idempotent_create_and_delete() {
    let idx = TempIndex::new();
    let o = run(&["index", "create", &idx.0, "--if-not-exists"]);
    assert_eq!(code(&o), 0);
    let v = stdout_json(&o);
    assert_eq!(v["skipped"], true);
    assert_eq!(v["reason"], "already_exists");

    let missing = unique_index();
    let o = run(&["index", "delete", &missing, "--if-exists"]);
    assert_eq!(code(&o), 0);
    assert_eq!(stdout_json(&o)["reason"], "not_found");
}

#[test]
fn documents_wait_select_and_dry_run() {
    let idx = TempIndex::new();
    let o = run_stdin(
        &["document", "add", &idx.0, "--format", "ndjson", "--wait"],
        b"{\"id\":1,\"title\":\"Dune\",\"year\":1965}\n{\"id\":2,\"title\":\"Emma\",\"year\":1815}\n",
    );
    assert_eq!(code(&o), 0, "{}", String::from_utf8_lossy(&o.stderr));
    let task = stdout_json(&o);
    assert_eq!(task["status"], "succeeded");
    assert_eq!(task["details"]["indexedDocuments"], 2);

    let o = run(&["search", &idx.0, "dune", "--select", "id"]);
    let v = stdout_json(&o);
    assert_eq!(v["hits"], json!([{"id": 1}]));
    assert!(v["estimatedTotalHits"].is_number());

    let o = run(&["document", "delete-all", &idx.0, "--dry-run"]);
    let v = stdout_json(&o);
    assert_eq!(v["dryRun"], true);
    assert_eq!(v["matchedDocuments"], 2);
    // Nothing was deleted.
    let o = run(&["index", "stats", &idx.0, "--select", "numberOfDocuments"]);
    assert_eq!(stdout_json(&o)["numberOfDocuments"], 2);
}

#[test]
fn settings_dry_run_shows_changes_only() {
    let idx = TempIndex::new();
    let o = run_stdin(
        &["settings", "update", &idx.0, "--dry-run"],
        br#"{"searchableAttributes": ["title"], "stopWords": []}"#,
    );
    assert_eq!(code(&o), 0, "{}", String::from_utf8_lossy(&o.stderr));
    let v = stdout_json(&o);
    assert_eq!(
        v["changes"],
        json!({"searchableAttributes": {"from": ["*"], "to": ["title"]}})
    );
    let o = run(&["settings", "get", &idx.0, "searchable-attributes"]);
    assert_eq!(stdout_json(&o), json!(["*"]));
}

#[test]
fn import_returns_summary_and_events() {
    let idx = TempIndex::new();
    let o = run_stdin(&["import", &idx.0], br#"[{"id":1},{"id":2},{"id":3}]"#);
    assert_eq!(code(&o), 0, "{}", String::from_utf8_lossy(&o.stderr));
    let v = stdout_json(&o);
    assert_eq!(v["status"], "succeeded");
    assert_eq!(v["indexedDocuments"], 3);
    assert!(o.stderr.is_empty(), "no status text in JSON mode");

    let o = run_stdin(
        &["import", &idx.0, "--events", "--batch-size", "12"],
        br#"[{"id":4},{"id":5}]"#,
    );
    let events: Vec<Value> = String::from_utf8_lossy(&o.stdout)
        .lines()
        .map(|l| serde_json::from_str(l).unwrap())
        .collect();
    assert_eq!(events.first().unwrap()["event"], "batch_enqueued");
    let done = events.last().unwrap();
    assert_eq!(done["event"], "done");
    assert_eq!(done["summary"]["indexedDocuments"], 2);
}

#[test]
fn project_commands_are_non_interactive() {
    let cfg = config_path(&format!("projects-{}", uuid::Uuid::new_v4().simple()));
    let p = |args: &[&str]| {
        Command::new(env!("CARGO_BIN_EXE_msc"))
            .args(args)
            .env("MSC_CONFIG", &cfg)
            .env_remove("MSC_URL")
            .env_remove("MSC_API_KEY")
            .stdin(Stdio::null())
            .output()
            .unwrap()
    };
    let o = p(&["project", "add", "staging"]);
    assert_eq!(code(&o), 2);
    assert_eq!(stderr_error(&o)["code"], "non_interactive");

    let o = p(&[
        "project",
        "add",
        "staging",
        "--url",
        "http://s:7700",
        "--api-key",
        "k",
    ]);
    assert_eq!(code(&o), 0);
    let v = stdout_json(&o);
    assert_eq!(v["apiKeySet"], true);
    assert!(v.get("apiKey").is_none(), "never print keys");

    assert_eq!(
        code(&p(&["project", "add", "staging", "--url", "http://x"])),
        2
    );
    assert_eq!(
        code(&p(&["project", "add", "staging", "--if-not-exists"])),
        0
    );

    let o = p(&["project", "update", "staging", "--remove-api-key"]);
    assert_eq!(stdout_json(&o)["apiKeySet"], false);

    let o = p(&["project", "list", "--select", "name"]);
    let names: Vec<Value> = stdout_json(&o)["results"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| r["name"].clone())
        .collect();
    assert!(names.contains(&json!("staging")));

    assert_eq!(code(&p(&["project", "remove", "nope", "--if-exists"])), 0);
    let _ = std::fs::remove_file(&cfg);
}

#[test]
fn schema_lists_commands_and_exit_codes() {
    let o = run(&["schema"]);
    let v = stdout_json(&o);
    assert_eq!(
        v["exitCodes"]["7"].as_str().unwrap().split(':').next(),
        Some("task_failed")
    );
    assert!(
        v["globalArgs"]
            .as_array()
            .unwrap()
            .iter()
            .any(|a| a["name"] == "wait")
    );
    let o = run(&["schema", "index", "delete"]);
    let v = stdout_json(&o);
    let names: Vec<&str> = v["args"]
        .as_array()
        .unwrap()
        .iter()
        .map(|a| a["name"].as_str().unwrap())
        .collect();
    assert_eq!(names, ["uid", "if_exists", "dry_run"]);
    assert_eq!(code(&run(&["schema", "nope"])), 2);
}

#[test]
fn mcp_server_lists_and_calls_tools() {
    let idx = unique_index();
    let requests = [
        json!({"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {"protocolVersion": "2025-06-18", "capabilities": {}, "clientInfo": {"name": "test", "version": "0"}}}),
        json!({"jsonrpc": "2.0", "method": "notifications/initialized"}),
        json!({"jsonrpc": "2.0", "id": 2, "method": "tools/list"}),
        json!({"jsonrpc": "2.0", "id": 3, "method": "tools/call", "params": {"name": "index_create", "arguments": {"uid": idx, "primary_key": "id", "wait": true}}}),
        json!({"jsonrpc": "2.0", "id": 4, "method": "tools/call", "params": {"name": "document_add", "arguments": {"uid": idx, "input": [{"id": 1, "title": "Dune"}], "wait": true}}}),
        json!({"jsonrpc": "2.0", "id": 5, "method": "tools/call", "params": {"name": "search", "arguments": {"uid": idx, "query": "dune", "select": ["title"]}}}),
        json!({"jsonrpc": "2.0", "id": 6, "method": "tools/call", "params": {"name": "index_get", "arguments": {"uid": unique_index()}}}),
        json!({"jsonrpc": "2.0", "id": 7, "method": "tools/call", "params": {"name": "index_delete", "arguments": {"uid": idx, "wait": true}}}),
        json!({"jsonrpc": "2.0", "id": 8, "method": "nope"}),
    ];
    let input: String = requests.iter().map(|r| format!("{r}\n")).collect();
    let o = run_stdin(&["mcp"], input.as_bytes());
    assert_eq!(code(&o), 0, "{}", String::from_utf8_lossy(&o.stderr));
    let responses: Vec<Value> = String::from_utf8_lossy(&o.stdout)
        .lines()
        .map(|l| serde_json::from_str(l).unwrap())
        .collect();
    // The notification gets no response.
    assert_eq!(responses.len(), requests.len() - 1);
    let by_id = |id: i64| responses.iter().find(|r| r["id"] == id).unwrap().clone();

    assert_eq!(by_id(1)["result"]["serverInfo"]["name"], "msc");
    let tools = by_id(2)["result"]["tools"].as_array().unwrap().clone();
    assert!(tools.iter().any(|t| t["name"] == "search"));
    assert!(!tools.iter().any(|t| t["name"] == "settings_edit"));

    let text = |id: i64| -> Value {
        serde_json::from_str(by_id(id)["result"]["content"][0]["text"].as_str().unwrap()).unwrap()
    };
    assert_eq!(text(3)["status"], "succeeded");
    assert_eq!(text(4)["status"], "succeeded");
    assert_eq!(text(5)["hits"], json!([{"title": "Dune"}]));
    assert_eq!(by_id(6)["result"]["isError"], true);
    assert_eq!(text(6)["error"]["kind"], "not_found");
    assert_eq!(text(7)["status"], "succeeded");
    assert_eq!(by_id(8)["error"]["code"], -32601);
}

#[test]
fn plugin_manifest_matches_crate() {
    let root = env!("CARGO_MANIFEST_DIR");
    let plugin: Value = serde_json::from_str(
        &std::fs::read_to_string(format!("{root}/.claude-plugin/plugin.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        plugin["version"],
        env!("CARGO_PKG_VERSION"),
        "bump plugin.json with Cargo.toml"
    );
    assert_eq!(plugin["mcpServers"]["meilisearch"]["args"], json!(["mcp"]));
    let market: Value = serde_json::from_str(
        &std::fs::read_to_string(format!("{root}/.claude-plugin/marketplace.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(market["plugins"][0]["name"], plugin["name"]);
}

#[test]
fn skill_install_and_uninstall() {
    let dir = tempfile::tempdir().unwrap();
    let d = dir.path().to_str().unwrap();
    let o = run(&["skill", "install", "--dir", d]);
    assert_eq!(code(&o), 0);
    assert_eq!(stdout_json(&o)["results"][0]["status"], "installed");
    let installed = std::fs::read_to_string(dir.path().join("msc/SKILL.md")).unwrap();
    assert_eq!(
        installed.as_bytes(),
        run(&["skill", "show"]).stdout.as_slice()
    );
    let o = run(&["skill", "uninstall", "--dir", d]);
    assert_eq!(stdout_json(&o)["results"][0]["removed"], true);
    assert!(!dir.path().join("msc").exists());
}

#[test]
fn api_escape_hatch_reaches_any_route() {
    let idx = TempIndex::new();
    let path = format!("/indexes/{}/documents", idx.0);
    let o = run_stdin(
        &[
            "api",
            "POST",
            &path,
            "--content-type",
            "application/x-ndjson",
            "--wait",
        ],
        b"{\"id\":1,\"title\":\"Dune\"}\n",
    );
    assert_eq!(code(&o), 0, "{}", String::from_utf8_lossy(&o.stderr));
    assert_eq!(stdout_json(&o)["status"], "succeeded");

    let o = run(&["api", "get", &path, "-p", "fields=id", "-p", "limit=1"]);
    assert_eq!(stdout_json(&o)["results"], json!([{"id": 1}]));

    let o = run(&["api", "GET", &format!("/indexes/{}", unique_index())]);
    assert_eq!(code(&o), 4);
    assert_eq!(code(&run(&["api", "GET", "indexes"])), 2);
    assert_eq!(code(&run(&["api", "POST", "/indexes", "-d", "{nope"])), 2);
}

#[test]
fn search_body_merges_extra_parameters() {
    let idx = TempIndex::new();
    let o = run_stdin(
        &["document", "add", &idx.0, "--wait"],
        br#"[{"id":1,"title":"Dune"}]"#,
    );
    assert_eq!(code(&o), 0);
    let o = run(&[
        "search",
        &idx.0,
        "dune",
        "--limit",
        "5",
        "--body",
        r#"{"showRankingScore":true,"limit":1}"#,
    ]);
    let v = stdout_json(&o);
    assert_eq!(v["limit"], 1, "--body overrides flags");
    assert!(v["hits"][0]["_rankingScore"].is_number());
    assert_eq!(code(&run(&["search", &idx.0, "x", "--body", "[1]"])), 2);
}

#[test]
fn whoami_reports_target_and_auth() {
    let o = run(&["whoami"]);
    assert_eq!(code(&o), 0, "{}", String::from_utf8_lossy(&o.stderr));
    let v = stdout_json(&o);
    assert_eq!(v["url"], test_url());
    assert_eq!(v["source"], "env MSC_URL");
    assert_eq!(v["reachable"], true);
    assert_eq!(v["auth"], "ok");

    let o = run(&["whoami", "--url", "http://127.0.0.1:9"]);
    assert_eq!(code(&o), 6);
    assert_eq!(stdout_json(&o)["reachable"], false);
}

#[test]
fn table_output_is_explicit_and_tabular() {
    let o = run(&["health", "--table"]);
    let text = String::from_utf8_lossy(&o.stdout);
    assert!(text.starts_with("key     value"), "{text}");
    assert!(text.contains("status  available"));
    assert_eq!(code(&run(&["health", "--table", "--json"])), 2);
}

use std::path::PathBuf;

use anyhow::Result;
use clap::Args;

use serde_json::json;

use super::{Cli, build_client, print_json, read_json_input};
use crate::error::CliError;

#[derive(Args)]
pub struct SearchArgs {
    /// Index UID
    #[arg(value_name = "INDEX_UID")]
    pub uid: String,

    /// Search query
    pub query: Option<String>,

    /// Filter expression
    #[arg(long)]
    pub filter: Option<String>,

    /// Facets to return
    #[arg(long, value_delimiter = ',')]
    pub facets: Option<Vec<String>>,

    /// Maximum number of results
    #[arg(long)]
    pub limit: Option<u64>,

    /// Result offset
    #[arg(long)]
    pub offset: Option<u64>,

    /// Sort rules
    #[arg(long, value_delimiter = ',')]
    pub sort: Option<Vec<String>>,

    /// Attributes to retrieve
    #[arg(long, value_delimiter = ',')]
    pub attributes_to_retrieve: Option<Vec<String>>,

    /// Attributes to highlight
    #[arg(long, value_delimiter = ',')]
    pub attributes_to_highlight: Option<Vec<String>>,

    /// Extra search parameters as a JSON object, merged over the flags
    /// (e.g. '{"hybrid":{"embedder":"default"},"showRankingScore":true}')
    #[arg(long, value_name = "JSON")]
    pub body: Option<String>,

    /// Interactive TUI mode
    #[arg(short, long)]
    pub interactive: bool,
}

/// Build the search request from flags, then overlay `--body`.
fn request_body(args: &SearchArgs) -> Result<serde_json::Value> {
    let mut body = json!({ "q": args.query.as_deref().unwrap_or("") });
    let mut set = |k: &str, v: serde_json::Value| {
        body[k] = v;
    };
    if let Some(f) = &args.filter {
        set("filter", json!(f));
    }
    if let Some(f) = &args.facets {
        set("facets", json!(f));
    }
    if let Some(l) = args.limit {
        set("limit", json!(l));
    }
    if let Some(o) = args.offset {
        set("offset", json!(o));
    }
    if let Some(s) = &args.sort {
        set("sort", json!(s));
    }
    if let Some(a) = &args.attributes_to_retrieve {
        set("attributesToRetrieve", json!(a));
    }
    if let Some(a) = &args.attributes_to_highlight {
        set("attributesToHighlight", json!(a));
    }
    if let Some(raw) = &args.body {
        let extra: serde_json::Value = serde_json::from_str(raw).map_err(|e| {
            CliError::usage("invalid_json", format!("--body is not valid JSON: {e}"))
        })?;
        let Some(extra) = extra.as_object() else {
            return Err(CliError::usage("invalid_json", "--body must be a JSON object").into());
        };
        for (k, v) in extra {
            body[k] = v.clone();
        }
    }
    Ok(body)
}

pub async fn run(cli: &Cli, args: &SearchArgs) -> Result<()> {
    if args.interactive {
        crate::output::require_interactive(
            "Interactive search (-i)",
            "Run `msc search <INDEX_UID> <QUERY>` without -i",
        )?;
        let client = build_client(cli)?;
        return crate::tui::search::run_interactive_search(client, &args.uid).await;
    }

    let client = build_client(cli)?;
    let result = client
        .search_with_body(&args.uid, &request_body(args)?)
        .await?;
    print_json(&result);
    Ok(())
}

// ── Multi-Search ──────────────────────────────────────────────

#[derive(Args)]
pub struct MultiSearchArgs {
    /// JSON file with a queries array or a full body ({"queries": [...], "federation": {...}}); reads stdin if omitted
    #[arg(long)]
    pub file: Option<PathBuf>,
}

pub async fn run_multi_search(cli: &Cli, args: &MultiSearchArgs) -> Result<()> {
    let client = build_client(cli)?;
    let queries = read_json_input(args.file.as_deref())?;
    let result = client.multi_search(&queries).await?;
    print_json(&result);
    Ok(())
}

// ── Facet Search ──────────────────────────────────────────────

#[derive(Args)]
pub struct FacetSearchArgs {
    /// Index UID
    #[arg(value_name = "INDEX_UID")]
    pub uid: String,

    /// Facet name to search
    pub facet_name: String,

    /// Facet query string
    #[arg(long)]
    pub facet_query: Option<String>,

    /// Filter expression
    #[arg(long)]
    pub filter: Option<String>,
}

pub async fn run_facet_search(cli: &Cli, args: &FacetSearchArgs) -> Result<()> {
    let client = build_client(cli)?;
    let result = client
        .facet_search(
            &args.uid,
            &args.facet_name,
            args.facet_query.as_deref(),
            args.filter.as_deref(),
        )
        .await?;
    print_json(&result);
    Ok(())
}

// ── Similar Documents ─────────────────────────────────────────

#[derive(Args)]
pub struct SimilarArgs {
    /// Index UID
    #[arg(value_name = "INDEX_UID")]
    pub uid: String,

    /// Document ID to find similar documents for
    #[arg(value_name = "DOCUMENT_ID")]
    pub id: String,

    /// Maximum number of results
    #[arg(long)]
    pub limit: Option<u64>,

    /// Result offset
    #[arg(long)]
    pub offset: Option<u64>,

    /// Filter expression
    #[arg(long)]
    pub filter: Option<String>,

    /// Embedder to use
    #[arg(long)]
    pub embedder: Option<String>,
}

pub async fn run_similar(cli: &Cli, args: &SimilarArgs) -> Result<()> {
    let client = build_client(cli)?;
    let result = client
        .similar(
            &args.uid,
            &args.id,
            args.limit,
            args.offset,
            args.filter.as_deref(),
            args.embedder.as_deref(),
        )
        .await?;
    print_json(&result);
    Ok(())
}

use anyhow::Result;
use crossterm::event::{self, Event, KeyCode, KeyModifiers};
use crossterm::terminal::{self, EnterAlternateScreen, LeaveAlternateScreen};
use ratatui::Terminal;
use ratatui::backend::CrosstermBackend;
use ratatui::layout::{Constraint, Direction, Layout};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, Borders, List, ListItem, Paragraph};
use std::io;
use std::time::{Duration, Instant};

use crate::client::MeiliClient;

struct SearchState {
    query: String,
    results: Vec<serde_json::Value>,
    selected: usize,
    total_hits: u64,
    processing_time_ms: u64,
    last_search: Instant,
    expanded: Option<usize>,
}

pub async fn run_interactive_search(client: MeiliClient, uid: &str) -> Result<()> {
    terminal::enable_raw_mode()?;
    let mut stdout = io::stdout();
    crossterm::execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut state = SearchState {
        query: String::new(),
        results: vec![],
        selected: 0,
        total_hits: 0,
        processing_time_ms: 0,
        last_search: Instant::now(),
        expanded: None,
    };

    let debounce = Duration::from_millis(150);
    let mut needs_search = false;

    loop {
        terminal.draw(|f| {
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Length(3),
                    Constraint::Min(5),
                    Constraint::Length(1),
                ])
                .split(f.area());

            // Search input
            let input = Paragraph::new(state.query.as_str())
                .block(
                    Block::default()
                        .title(format!(" Search: {} ", uid))
                        .borders(Borders::ALL),
                )
                .style(Style::default().fg(Color::Yellow));
            f.render_widget(input, chunks[0]);

            // Results
            if let Some(idx) = state.expanded {
                if let Some(doc) = state.results.get(idx) {
                    let json = serde_json::to_string_pretty(doc).unwrap_or_default();
                    let para = Paragraph::new(json)
                        .block(
                            Block::default()
                                .title(" Document (Esc to close) ")
                                .borders(Borders::ALL),
                        )
                        .style(Style::default().fg(Color::White));
                    f.render_widget(para, chunks[1]);
                }
            } else {
                let items: Vec<ListItem> = state
                    .results
                    .iter()
                    .enumerate()
                    .map(|(i, doc)| {
                        let display = doc
                            .as_object()
                            .map(|obj| {
                                obj.iter()
                                    .take(3)
                                    .map(|(k, v)| {
                                        format!(
                                            "{}: {}",
                                            k,
                                            match v {
                                                serde_json::Value::String(s) => {
                                                    if s.len() > 60 {
                                                        format!("{}...", &s[..60])
                                                    } else {
                                                        s.clone()
                                                    }
                                                }
                                                other => other.to_string(),
                                            }
                                        )
                                    })
                                    .collect::<Vec<_>>()
                                    .join(" | ")
                            })
                            .unwrap_or_else(|| doc.to_string());

                        let style = if i == state.selected {
                            Style::default()
                                .fg(Color::Black)
                                .bg(Color::Cyan)
                                .add_modifier(Modifier::BOLD)
                        } else {
                            Style::default()
                        };
                        ListItem::new(Line::from(vec![Span::styled(display, style)]))
                    })
                    .collect();

                let list = List::new(items)
                    .block(Block::default().title(" Results ").borders(Borders::ALL));
                f.render_widget(list, chunks[1]);
            }

            // Status bar
            let status = Line::from(vec![Span::styled(
                format!(
                    " {} hits in {}ms | ↑↓ navigate | Enter expand | q quit ",
                    state.total_hits, state.processing_time_ms
                ),
                Style::default().fg(Color::DarkGray),
            )]);
            let status_bar = Paragraph::new(status);
            f.render_widget(status_bar, chunks[2]);
        })?;

        if event::poll(Duration::from_millis(50))?
            && let Event::Key(key) = event::read()?
        {
            match key.code {
                KeyCode::Char('q') if state.expanded.is_none() => break,
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => break,
                KeyCode::Esc => {
                    if state.expanded.is_some() {
                        state.expanded = None;
                    } else {
                        break;
                    }
                }
                KeyCode::Char(c) if state.expanded.is_none() => {
                    state.query.push(c);
                    needs_search = true;
                    state.last_search = Instant::now();
                }
                KeyCode::Backspace if state.expanded.is_none() => {
                    state.query.pop();
                    needs_search = true;
                    state.last_search = Instant::now();
                }
                KeyCode::Up if state.selected > 0 => {
                    state.selected -= 1;
                }
                KeyCode::Up => {}
                KeyCode::Down if state.selected + 1 < state.results.len() => {
                    state.selected += 1;
                }
                KeyCode::Down => {}
                KeyCode::Enter => {
                    if state.expanded.is_some() {
                        state.expanded = None;
                    } else if !state.results.is_empty() {
                        state.expanded = Some(state.selected);
                    }
                }
                _ => {}
            }
        }

        // Debounced search
        if needs_search && state.last_search.elapsed() >= debounce {
            needs_search = false;
            if !state.query.is_empty() {
                if let Ok(result) = client
                    .search(
                        uid,
                        &state.query,
                        None,
                        None,
                        Some(20),
                        None,
                        None,
                        None,
                        None,
                    )
                    .await
                {
                    state.results = result["hits"].as_array().cloned().unwrap_or_default();
                    state.total_hits = result["estimatedTotalHits"].as_u64().unwrap_or(0);
                    state.processing_time_ms = result["processingTimeMs"].as_u64().unwrap_or(0);
                    state.selected = 0;
                    state.expanded = None;
                }
            } else {
                state.results.clear();
                state.total_hits = 0;
                state.processing_time_ms = 0;
            }
        }
    }

    terminal::disable_raw_mode()?;
    crossterm::execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    Ok(())
}

//! `msc api`: call any Meilisearch route with the CLI's auth, errors and
//! `--wait`, for endpoints and parameters that have no dedicated command.

use std::path::PathBuf;

use anyhow::Result;
use clap::{Args, ValueEnum};

use super::{Cli, build_client, print_json, read_input};
use crate::error::CliError;

#[derive(Clone, Copy, Debug, ValueEnum)]
#[value(rename_all = "UPPER")]
pub enum Method {
    #[value(alias = "get")]
    Get,
    #[value(alias = "post")]
    Post,
    #[value(alias = "put")]
    Put,
    #[value(alias = "patch")]
    Patch,
    #[value(alias = "delete")]
    Delete,
}

impl From<Method> for reqwest::Method {
    fn from(m: Method) -> Self {
        match m {
            Method::Get => reqwest::Method::GET,
            Method::Post => reqwest::Method::POST,
            Method::Put => reqwest::Method::PUT,
            Method::Patch => reqwest::Method::PATCH,
            Method::Delete => reqwest::Method::DELETE,
        }
    }
}

#[derive(Args)]
pub struct ApiArgs {
    /// HTTP method
    #[arg(value_enum, ignore_case = true)]
    pub method: Method,

    /// Route path, e.g. /indexes/movies/settings
    pub path: String,

    /// Inline JSON request body
    #[arg(long, short = 'd', conflicts_with = "file")]
    pub data: Option<String>,

    /// Request body file (reads stdin when piped and no --data is given)
    #[arg(long)]
    pub file: Option<PathBuf>,

    /// Query parameter as KEY=VALUE (repeatable)
    #[arg(long = "param", short = 'p', value_name = "KEY=VALUE")]
    pub params: Vec<String>,

    /// Content-Type of the body (e.g. application/x-ndjson, text/csv)
    #[arg(long, default_value = "application/json")]
    pub content_type: String,
}

fn parse_params(params: &[String]) -> Result<Vec<(String, String)>> {
    params
        .iter()
        .map(|p| {
            p.split_once('=')
                .map(|(k, v)| (k.to_string(), v.to_string()))
                .ok_or_else(|| {
                    CliError::usage(
                        "invalid_param",
                        format!("Invalid --param '{p}': expected KEY=VALUE"),
                    )
                    .into()
                })
        })
        .collect()
}

pub async fn run(cli: &Cli, args: &ApiArgs) -> Result<()> {
    if !args.path.starts_with('/') {
        return Err(CliError::usage(
            "invalid_path",
            format!("Path must start with '/': {}", args.path),
        )
        .with_hint("For example: msc api GET /indexes/movies/settings")
        .into());
    }
    let query = parse_params(&args.params)?;

    let body = if let Some(data) = &args.data {
        Some(data.clone().into_bytes())
    } else if args.file.is_some() {
        Some(read_input(args.file.as_deref())?)
    } else if !matches!(args.method, Method::Get) && stdin_has_data() {
        Some(read_input(None)?).filter(|b| !b.is_empty())
    } else {
        None
    };
    if let Some(bytes) = &body
        && args.content_type == "application/json"
        && let Err(e) = serde_json::from_slice::<serde_json::Value>(bytes)
    {
        return Err(CliError::usage(
            "invalid_json",
            format!("Request body is not valid JSON: {e}"),
        )
        .into());
    }

    let client = build_client(cli)?;
    let result = client
        .request(
            args.method.into(),
            &args.path,
            &query,
            body.map(|b| (b, args.content_type.clone())),
        )
        .await?;
    match &result {
        // Plain-text routes like /metrics print as-is.
        serde_json::Value::String(text) if !crate::output::is_json() => println!("{text}"),
        serde_json::Value::Null => {}
        other => print_json(other),
    }
    Ok(())
}

/// Stdin is a pipe or file (not a terminal), so a body may be waiting there.
fn stdin_has_data() -> bool {
    use std::io::IsTerminal;
    !std::io::stdin().is_terminal()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn params_parse_key_value() {
        let p = parse_params(&["limit=5".into(), "fields=a,b".into()]).unwrap();
        assert_eq!(p[1], ("fields".to_string(), "a,b".to_string()));
        assert!(parse_params(&["nope".into()]).is_err());
    }
}

//! `msc mcp`: a Model Context Protocol server over stdio (newline-delimited
//! JSON-RPC 2.0). Every runnable command becomes a tool, generated from the
//! same clap tree as `msc schema`; a tool call runs `msc` itself with `--json`
//! so behavior, output and errors are identical to the CLI.

use std::process::Stdio;
use std::time::Duration;

use anyhow::{Context, Result};
use clap::Args;
use serde_json::{Map, Value, json};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};

use super::Cli;
use super::schema::{self, ArgSpec, ArgType, CommandSpec};

#[derive(Args)]
pub struct McpArgs {
    /// Only expose read-only tools (list, get, search, …)
    #[arg(long)]
    pub read_only: bool,

    /// Only expose these tools (comma-separated names; a trailing * matches a prefix, e.g. index_*,search)
    #[arg(long, value_delimiter = ',')]
    pub tools: Option<Vec<String>>,
}

const PROTOCOL_VERSIONS: &[&str] = &["2025-06-18", "2025-03-26", "2024-11-05"];

/// Commands that need a terminal, never terminate, or make no sense as tools.
const EXCLUDED: &[&[&str]] = &[
    &["mcp"],
    &["schema"],
    &["completions"],
    &["self-update"],
    &["settings", "edit"],
    &["task", "watch"],
    &["log", "stream"],
    &["skill", "list"],
    &["skill", "show"],
    &["skill", "install"],
    &["skill", "uninstall"],
];

/// Arguments dropped from tools (interactive or streaming modes).
const EXCLUDED_ARGS: &[&str] = &["interactive", "events", "follow"];

const READ_ONLY: &[&str] = &[
    "list",
    "get",
    "stats",
    "search",
    "multi-search",
    "facet-search",
    "similar",
    "health",
    "version",
    "metrics",
    "current",
    "status",
    "diff",
    "fetch",
    "wait",
    "whoami",
];

const INSTRUCTIONS: &str = "Tools for a Meilisearch instance, backed by the `msc` CLI. \
Write operations (adding documents, changing settings, creating or deleting indexes) are \
asynchronous: they return a summarized task with a `taskUid`. Pass `wait: true` to get the \
finished task instead, or call `task_wait`. Use `select` to keep only the fields you need \
from large results. Errors come back as JSON with `kind`, `code`, `message` and often a `hint`.";

struct Tool {
    name: String,
    spec: CommandSpec,
    read_only: bool,
}

impl Tool {
    fn args(&self) -> impl Iterator<Item = &ArgSpec> {
        self.spec
            .args
            .iter()
            .filter(|a| !EXCLUDED_ARGS.contains(&a.name.as_str()))
    }

    fn takes_input(&self) -> bool {
        self.spec.args.iter().any(|a| a.name == "file")
    }

    fn definition(&self) -> Value {
        let mut properties = Map::new();
        let mut required = vec![];
        for arg in self.args() {
            properties.insert(arg.name.clone(), property_schema(arg));
            if arg.required {
                required.push(arg.name.clone());
            }
        }
        if self.takes_input() {
            properties.insert(
                "input".into(),
                json!({
                    "description": "Inline content to send instead of `file` (a JSON value, or a string for NDJSON/CSV)",
                }),
            );
        }
        properties.insert(
            "project".into(),
            json!({"type": "string", "description": "msc project name"}),
        );
        properties.insert(
            "select".into(),
            json!({"type": "array", "items": {"type": "string"}, "description": "Fields to keep (dot paths)"}),
        );
        if !self.read_only {
            properties.insert(
                "wait".into(),
                json!({"type": "boolean", "description": "Return the finished task"}),
            );
        }

        let path = self.spec.path.join(" ");
        let leaf = self.spec.path.last().map(String::as_str).unwrap_or("");
        let destructive = !self.read_only
            && ([
                "delete", "reset", "remove", "swap", "cancel", "stop", "promote", "api",
            ]
            .iter()
            .any(|w| leaf.contains(w)));
        json!({
            "name": self.name,
            "description": format!("{} (`msc {path}`)", self.spec.about),
            "inputSchema": {
                "type": "object",
                "properties": properties,
                "required": required,
                "additionalProperties": false,
            },
            "annotations": {
                "title": format!("msc {path}"),
                "readOnlyHint": self.read_only,
                "destructiveHint": destructive,
                "openWorldHint": false,
            },
        })
    }

    /// Translate tool arguments into a `msc` argv and optional stdin payload.
    fn argv(
        &self,
        arguments: &Map<String, Value>,
    ) -> Result<(Vec<String>, Option<Vec<u8>>), String> {
        let mut argv: Vec<String> = self.spec.path.clone();
        argv.extend(["--json".into(), "--quiet".into()]);
        let mut positionals = vec![];
        let mut input = None;

        for (key, value) in arguments {
            if value.is_null() {
                continue;
            }
            match key.as_str() {
                "input" if self.takes_input() => {
                    input = Some(match value {
                        Value::String(s) => s.clone().into_bytes(),
                        other => serde_json::to_vec(other).unwrap_or_default(),
                    });
                    continue;
                }
                "project" => {
                    argv.extend(["--project".into(), scalar(value)]);
                    continue;
                }
                "select" => {
                    argv.extend(["--select".into(), list(value).join(",")]);
                    continue;
                }
                "wait" if !self.read_only => {
                    if value.as_bool() == Some(true) {
                        argv.push("--wait".into());
                    }
                    continue;
                }
                _ => {}
            }
            let Some(arg) = self.args().find(|a| &a.name == key) else {
                return Err(format!("Unknown argument `{key}` for tool `{}`", self.name));
            };
            if arg.positional {
                positionals.push((arg.name.clone(), value.clone()));
                continue;
            }
            let flag = format!("--{}", arg.long.as_deref().unwrap_or(&arg.name));
            if arg.ty == ArgType::Boolean {
                if value.as_bool() == Some(true) {
                    argv.push(flag);
                }
            } else if arg.multiple {
                let values = list(value);
                match arg.delimiter {
                    Some(d) => argv.extend([flag, values.join(&d.to_string())]),
                    None => {
                        for v in values {
                            argv.extend([flag.clone(), v]);
                        }
                    }
                }
            } else {
                argv.extend([flag, scalar(value)]);
            }
        }

        // Positionals go last, after `--`, in declaration order.
        let order: Vec<&str> = self
            .args()
            .filter(|a| a.positional)
            .map(|a| a.name.as_str())
            .collect();
        positionals.sort_by_key(|(name, _)| order.iter().position(|n| n == name));
        if !positionals.is_empty() {
            argv.push("--".into());
            for (_, v) in positionals {
                argv.extend(list(&v));
            }
        }
        Ok((argv, input))
    }
}

fn property_schema(arg: &ArgSpec) -> Value {
    let item_type = arg.ty_name();
    let mut v = if arg.multiple {
        json!({"type": "array", "items": {"type": item_type}})
    } else {
        json!({"type": item_type})
    };
    if !arg.help.is_empty() {
        v["description"] = json!(arg.help);
    }
    if !arg.possible_values.is_empty() {
        v["enum"] = json!(arg.possible_values);
    }
    if let Some(d) = &arg.default {
        v["default"] = match arg.ty {
            ArgType::Integer => d.parse::<i64>().map(Value::from).unwrap_or(json!(d)),
            _ => json!(d),
        };
    }
    v
}

impl ArgSpec {
    fn ty_name(&self) -> &'static str {
        match self.ty {
            ArgType::Boolean => "boolean",
            ArgType::Integer => "integer",
            ArgType::String => "string",
        }
    }
}

fn scalar(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        other => other.to_string(),
    }
}

fn list(v: &Value) -> Vec<String> {
    match v {
        Value::Array(items) => items.iter().map(scalar).collect(),
        other => vec![scalar(other)],
    }
}

fn matches(name: &str, patterns: &[String]) -> bool {
    patterns.iter().any(|p| match p.strip_suffix('*') {
        Some(prefix) => name.starts_with(prefix),
        None => name == p,
    })
}

fn tools() -> Vec<Tool> {
    let root = schema::root();
    root.leaves()
        .into_iter()
        .filter(|c| {
            !EXCLUDED
                .iter()
                .any(|ex| c.path.iter().map(String::as_str).eq(ex.iter().copied()))
        })
        .map(|c| Tool {
            name: c.path.join("_").replace('-', "_"),
            read_only: c
                .path
                .last()
                .is_some_and(|l| READ_ONLY.contains(&l.as_str())),
            spec: c.clone(),
        })
        .collect()
}

pub async fn run(cli: &Cli, args: &McpArgs) -> Result<()> {
    let tools: Vec<Tool> = tools()
        .into_iter()
        .filter(|t| !args.read_only || t.read_only)
        .filter(|t| args.tools.as_ref().is_none_or(|p| matches(&t.name, p)))
        .collect();
    let exe = std::env::current_exe().context("Cannot locate the msc executable")?;
    // Forward connection settings given to `msc mcp` to every tool call.
    let mut env = vec![];
    if let Some(p) = &cli.project {
        env.push(("MSC_PROJECT", p.clone()));
    }
    if let Some(u) = &cli.url {
        env.push(("MSC_URL", u.clone()));
    }
    if let Some(k) = &cli.api_key {
        env.push(("MSC_API_KEY", k.clone()));
    }

    let mut lines = BufReader::new(tokio::io::stdin()).lines();
    let mut stdout = tokio::io::stdout();
    while let Some(line) = lines.next_line().await? {
        if line.trim().is_empty() {
            continue;
        }
        let response = match serde_json::from_str::<Value>(&line) {
            Ok(msg) => handle(&msg, &tools, &exe, &env).await,
            Err(e) => Some(rpc_error(Value::Null, -32700, &format!("Parse error: {e}"))),
        };
        if let Some(resp) = response {
            let mut out = serde_json::to_vec(&resp)?;
            out.push(b'\n');
            stdout.write_all(&out).await?;
            stdout.flush().await?;
        }
    }
    Ok(())
}

async fn handle(
    msg: &Value,
    tools: &[Tool],
    exe: &std::path::Path,
    env: &[(&str, String)],
) -> Option<Value> {
    let id = msg.get("id").cloned();
    let method = msg["method"].as_str().unwrap_or("");
    // Notifications get no response.
    let id = id?;

    let result = match method {
        "initialize" => {
            let requested = msg["params"]["protocolVersion"].as_str().unwrap_or("");
            let version = if PROTOCOL_VERSIONS.contains(&requested) {
                requested
            } else {
                PROTOCOL_VERSIONS[0]
            };
            json!({
                "protocolVersion": version,
                "capabilities": { "tools": { "listChanged": false } },
                "serverInfo": { "name": "msc", "version": env!("CARGO_PKG_VERSION") },
                "instructions": INSTRUCTIONS,
            })
        }
        "ping" => json!({}),
        "tools/list" => json!({ "tools": tools.iter().map(Tool::definition).collect::<Vec<_>>() }),
        "tools/call" => {
            let name = msg["params"]["name"].as_str().unwrap_or("");
            let Some(tool) = tools.iter().find(|t| t.name == name) else {
                return Some(rpc_error(id, -32602, &format!("Unknown tool: {name}")));
            };
            let empty = Map::new();
            let arguments = msg["params"]["arguments"].as_object().unwrap_or(&empty);
            match tool.argv(arguments) {
                Ok((argv, input)) => call(exe, env, &argv, input).await,
                Err(e) => tool_result(&e, true),
            }
        }
        _ => {
            return Some(rpc_error(
                id,
                -32601,
                &format!("Method not found: {method}"),
            ));
        }
    };
    Some(json!({ "jsonrpc": "2.0", "id": id, "result": result }))
}

async fn call(
    exe: &std::path::Path,
    env: &[(&str, String)],
    argv: &[String],
    input: Option<Vec<u8>>,
) -> Value {
    let mut cmd = tokio::process::Command::new(exe);
    cmd.args(argv)
        .stdin(if input.is_some() {
            Stdio::piped()
        } else {
            Stdio::null()
        })
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .kill_on_drop(true);
    for (k, v) in env {
        cmd.env(k, v);
    }
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return tool_result(&format!("Failed to run msc: {e}"), true),
    };
    if let (Some(data), Some(mut stdin)) = (input, child.stdin.take()) {
        tokio::spawn(async move {
            let _ = stdin.write_all(&data).await;
        });
    }
    let timeout = std::env::var("MSC_MCP_TIMEOUT_SECS")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(600);
    let output =
        match tokio::time::timeout(Duration::from_secs(timeout), child.wait_with_output()).await {
            Ok(Ok(o)) => o,
            Ok(Err(e)) => return tool_result(&format!("Failed to run msc: {e}"), true),
            Err(_) => return tool_result(&format!("msc timed out after {timeout}s"), true),
        };
    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
    if output.status.success() {
        let text = if stdout.is_empty() {
            "{\"ok\":true}".to_string()
        } else {
            stdout
        };
        tool_result(&text, false)
    } else {
        let text = [stdout, stderr]
            .into_iter()
            .filter(|s| !s.is_empty())
            .collect::<Vec<_>>()
            .join("\n");
        tool_result(&text, true)
    }
}

fn tool_result(text: &str, is_error: bool) -> Value {
    json!({ "content": [{ "type": "text", "text": text }], "isError": is_error })
}

fn rpc_error(id: Value, code: i64, message: &str) -> Value {
    json!({ "jsonrpc": "2.0", "id": id, "error": { "code": code, "message": message } })
}

