default = "local"

[projects.local]
type = "local"
url = "http://127.0.0.1:7700"
api_key = "[REDACTED]"
data_dir = "~/.local/share/msc/local"
binary = "~/.local/share/msc/bin/meilisearch-server"

[projects.production]
url = "https://my-instance.meilisearch.io"
api_key = "[REDACTED]"

[projects.staging]
